{'code': "from qgis.PyQt.QtWidgets import QAction, QToolBar
mw = iface.mainWindow()
action = mw.findChild(QAction, 'mActionToggleVectorToolBar')
if action is None:
    cands = [(a.objectName(), a.text()) for a in mw.findChildren(QAction) if 'ベクタツールバー' in a.text()]
    result = {'action': None, 'candidates': cands}
else:
    action.trigger()
    tb = mw.findChild(QToolBar, 'mVectorToolBar')
    result = {'action': action.objectName(), 'checked': action.isChecked(), 'toolbar_visible': tb.isVisible() if tb else None}"}
